SELECT topic,count() AS answers,countIf(result='correct')/count() AS correct_rate FROM knowledge_analytics.training_answers WHERE $__timeFilter(occurred_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring}) GROUP BY topic HAVING answers>=3 ORDER BY correct_rate,answers DESC LIMIT 20
